#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> grid(N, vector<int>(N));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            cin >> grid[i][j];
        }
    }

    vector<vector<bool>> visited(N, vector<bool>(N, false));
    vector<vector<bool>> inStack(N, vector<bool>(N, false));
    int loops = 0;

    function<void(int, int)> dfs = [&](int x, int y) {
        visited[x][y] = true;
        inStack[x][y] = true;

        int nx = grid[x][y] / N;
        int ny = grid[x][y] % N;

        if (!visited[nx][ny]) {
            dfs(nx, ny);
        } else if (inStack[nx][ny]) {
            // Found a loop
            loops++;
        }

        inStack[x][y] = false;
    };

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (!visited[i][j]) {
                dfs(i, j);
            }
        }
    }

    cout << loops << "\n";

    return 0;
}

