int main() {
    int n;
    while (cin >> n) {
        int total = n * n;
        vector<int> nxt(total);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int r, c;
                cin >> r >> c;
                r--; c--;  // 0-indexed
                nxt[i * n + j] = r * n + c;
            }
        }

        // Find number of cycles
        // 0 = unvisited, 1 = in current path, 2 = done
        vector<int> state(total, 0);
        vector<int> order; // track current path
        vector<int> pos(total, -1); // position in current path
        int cycles = 0;

        for (int start = 0; start < total; start++) {
            if (state[start] != 0) continue;

            // Traverse from start
            order.clear();
            int cur = start;
            while (cur != -1 && state[cur] == 0) {
                state[cur] = 1;
                pos[cur] = order.size();
                order.push_back(cur);
                cur = nxt[cur];
            }

            if (cur != -1 && state[cur] == 1) {
                // Found a new cycle
                cycles++;
                // Mark all nodes in the cycle as done
                int cycle_start_pos = pos[cur];
                for (int i = cycle_start_pos; i < (int)order.size(); i++) {
                    state[order[i]] = 2;
                }
            }

            // Mark all nodes in current path as done
            for (int node : order) {
                if (state[node] == 1) {
                    state[node] = 2;
                }
                pos[node] = -1;
            }
        }

        cout << cycles << endl;
    }
    return 0;
}

