/*
Each cell points to exactly one cell in an N x N grid.
So the whole floor is a functional graph with N^2 vertices.
In a functional graph, every connected component contains exactly one directed cycle.
Therefore, the number of "loops" equals the number of directed cycles.

We count cycles using DFS state coloring:
0 = unvisited
1 = visiting
2 = finished

When exploring u -> v:
- if v is unvisited, continue DFS
- if v is visiting, we found a new cycle
- if v is finished, nothing new

Input format assumed:
N
then for each of the N*N cells, a pair (r, c) meaning the next tile coordinates.
Coordinates are assumed to be 1-based in input.

Output:
number of loops
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    int V = N * N;
    vector<int> nxt(V);

    auto id = [N](int r, int c) {
        return r * N + c;
    };

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int r, c;
            cin >> r >> c;
            --r; --c;
            nxt[id(i, j)] = id(r, c);
        }
    }

    vector<int> state(V, 0);
    long long cycles = 0;

    function<void(int)> dfs = [&](int u) {
        state[u] = 1;
        int v = nxt[u];
        if (state[v] == 0) {
            dfs(v);
        } else if (state[v] == 1) {
            ++cycles;
        }
        state[u] = 2;
    };

    for (int i = 0; i < V; ++i) {
        if (state[i] == 0) dfs(i);
    }

    cout << cycles << '\n';
    return 0;
}

