public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());

        int[][] next = new int[N][N];
        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int j = 0; j < N; j++) {
                next[i][j] = Integer.parseInt(st.nextToken()) - 1; // 0-indexed
            }
        }

        int totalCells = N * N;
        int[] state = new int[totalCells]; // 0 = unvisited, 1 = visiting, 2 = processed
        int[] step = new int[totalCells]; // step number when visited
        int[] cycleId = new int[totalCells];
        Arrays.fill(cycleId, -1);

        int cycleCount = 0;

        for (int start = 0; start < totalCells; start++) {
            if (state[start] != 0) continue;

            int cur = start;
            int steps = 0;
            while (state[cur] == 0) {
                state[cur] = 1;
                step[cur] = steps++;
                int r = cur / N;
                int c = cur % N;
                cur = next[r][c];
            }

            if (state[cur] == 1) {
                // Found a cycle
                int cycleStart = cur;
                int cycleLength = steps - step[cycleStart];

                // Mark all nodes in this cycle
                int node = cycleStart;
                for (int i = 0; i < cycleLength; i++) {
                    cycleId[node] = cycleCount;
                    int r = node / N;
                    int c = node % N;
                    node = next[r][c];
                }
                cycleCount++;
            }

            // Mark all nodes visited in this DFS as processed
            cur = start;
            while (state[cur] == 1) {
                state[cur] = 2;
                int r = cur / N;
                int c = cur % N;
                cur = next[r][c];
            }
        }

        System.out.println(cycleCount);
    }
}

