/*
We are given an N x N grid. Each cell points to exactly one next cell.
Interpret the floor as a directed graph where every vertex has out-degree 1.
The number of "steady-state loops" equals the number of directed cycles
in this functional graph.

Input format (standard for this classic problem):
N
for each of N rows:
  N pairs (r, c) meaning the next tile coordinates of each cell

Coordinates are 1-based in input.

We count the number of cycles using DFS states:
0 = unvisited
1 = visiting
2 = done

When following edges:
- if next is unvisited, continue DFS
- if next is visiting, we found one new cycle
- if next is done, no new cycle from this path

Since each node has exactly one outgoing edge, this correctly counts all cycles.

Time: O(N^2)
Memory: O(N^2)
*/

public class Main {
    static int N;
    static int total;
    static int[] next;
    static byte[] state;

    static void dfs(int u) {
        state[u] = 1;
        int v = next[u];
        if (state[v] == 0) {
            dfs(v);
        } else if (state[v] == 1) {
            total++;
        }
        state[u] = 2;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        N = fs.nextInt();
        int size = N * N;
        next = new int[size];
        state = new byte[size];

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                int r = fs.nextInt() - 1;
                int c = fs.nextInt() - 1;
                int id = i * N + j;
                next[id] = r * N + c;
            }
        }

        total = 0;
        for (int i = 0; i < size; i++) {
            if (state[i] == 0) dfs(i);
        }

        System.out.println(total);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

