int N;
int *next_tile; // next_tile[i] = destination of tile i
int *state;     // 0=unvisited, 1=in progress, 2=done
int *order;     // order[i] = step number when node i was visited in current path
int cycle_count;

void dfs(int start) {
    // Iterative traversal
    int cur = start;
    int step = 0;

    // Follow the path until we hit a visited or in-progress node
    // We need to track the path
    int *path = (int*)malloc(N*N * sizeof(int));
    int path_len = 0;

    while (state[cur] == 0) {
        state[cur] = 1;
        order[cur] = step++;
        path[path_len++] = cur;
        cur = next_tile[cur];
    }

    if (state[cur] == 1) {
        // Found a cycle - cur is part of current path
        // The cycle starts at order[cur] in the path
        cycle_count++;
    }
    // If state[cur] == 2, no new cycle

    // Mark all nodes in path as done
    for (int i = 0; i < path_len; i++) {
        state[path[i]] = 2;
    }

    free(path);
}

