int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int total = N * N;
    int *to = (int *)malloc((size_t)total * sizeof(int));
    int *state = (int *)calloc((size_t)total, sizeof(int)); // 0=unvisited, 1=visiting, 2=done
    int *pos = (int *)malloc((size_t)total * sizeof(int));
    int *stack = (int *)malloc((size_t)total * sizeof(int));

    if (!to || !state || !pos || !stack) return 0;

    for (int i = 0; i < total; i++) pos[i] = -1;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int x, y;
            scanf("%d %d", &x, &y);
            x--; y--;
            to[i * N + j] = x * N + y;
        }
    }

    int cycles = 0;

    for (int s = 0; s < total; s++) {
        if (state[s] != 0) continue;

        int top = 0;
        int cur = s;

        while (1) {
            if (state[cur] == 0) {
                state[cur] = 1;
                pos[cur] = top;
                stack[top++] = cur;
                cur = to[cur];
            } else if (state[cur] == 1) {
                cycles++;
                for (int i = 0; i < top; i++) {
                    state[stack[i]] = 2;
                    pos[stack[i]] = -1;
                }
                break;
            } else { // state[cur] == 2
                for (int i = 0; i < top; i++) {
                    state[stack[i]] = 2;
                    pos[stack[i]] = -1;
                }
                break;
            }
        }
    }

    printf("%d\n", cycles);

    free(to);
    free(state);
    free(pos);
    free(stack);
    return 0;
}
